// Ewha Womans University, Sinchon campus (이화여자대학교 신촌캠퍼스, 서울 서대문구 대현동, 안산 자락). Data is generated by
// scripts/campuses/ewha/build-package.mjs from the pilot (pilot/ewha-sinchon; a copy of src/campuses/dongguk/index.js): the destructible
// models of active-models.json (ECC·본관(파이퍼홀)·대강당 detailed, the rest generic; every university building breaks), 대학교회 (religious)
// and 이화유치원 (child facility) as protected shield models (rule 10.1, user decision 2026-10-23), a baked ground drawn with the pilot's
// ground shader (the SKKU port src/campuses/skku/ground-look.js; the pilot's final-materials.js is the Dongguk / uos-seoul-v2 shader), the
// preview's own retaining walls / ribbons / skirts and planting (same trees), the place models of landscape/layout.json (ECC 큰 계단,
// 대강당 정면 돌계단 - never damaged) + landscape/sports.gltf, and the non-destructible context (대현동·봉원동·신촌·안산) fading into the
// haze. Local only until the user approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, EWHA_PLACEMENTS, EWHA_BUILDING_BASE, EWHA_HEIGHT_GRIDS, EWHA_HEIGHT_RANGE_M, EWHA_ENV_IDS, EWHA_ENV_MANIFEST_IDS, EWHA_LOOK, EWHA_ZONES, EWHA_DISPLAY, EWHA_PROVENANCE } from './data.js';
import { EWHA_FOOTPRINTS } from './footprints.js';
import { EWHA_PROTECTED } from './protected.js';
import { createSkkuGroundLook } from '../skku/ground-look.js';

const MODEL_IDS = Object.freeze(EWHA_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/ewha/${file}`, import.meta.url).href;
const HAZE = EWHA_DISPLAY.haze, FADE = EWHA_DISPLAY.fade;

export const EWHA = Object.freeze({
  id: 'ewha',
  meta: Object.freeze({ school: '이화여자대학교', campus: '신촌캠퍼스', short: '이화여대', modelNoun: '이화여대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: EWHA_PLACEMENTS,
  approvedCount: EWHA_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['ecc', 'mainHall', 'auditorium', 'library', 'posco'].filter(id => MODEL_IDS.includes(id))),
  // start / reset focus = 본관(파이퍼홀): ECC is 241 m long, so the package check's centre hits (radius 80 m) cannot clear it - the frame
  // below still centres the ECC valley.
  startBuildingId: 'mainHall',
  // Start: from over the south-west (정문 쪽) looking north-east along the ECC valley: the 정문 광장 (E -95 / N -140) at the bottom, the
  // ECC valley and its 큰 계단 (top E 50 / N 65) in the middle, 본관(파이퍼홀) (E 87 / N 133) at the top, 대강당 to the left.
  // Box in world units (metres x 0.5, z = -N): E -90..50 m, N -150..90 m, -12..28 m high; azimuth -0.61 = camera south-west.
  // Projected in Node with src/camera.js (scripts/campuses/ewha/start-frame-check.mjs, W1 2026-10-23): camera at E -229 / N -329 m,
  // 178 m up (1280x800; E -505 / N -723, 402 m up at 390x844); 정문 광장 at screen (646, 677) / (197, 527), 큰 계단 top (646, 291) /
  // (198, 368), 본관 roof (629, 193) / (189, 311), inside the HUD-free band 96..712 / 96..756; building share 0.44 / 0.29, 42 / 51 of 63 on screen.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-45, -6, -45]), max: Object.freeze([25, 14, 75]), azimuth: -0.61 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: EWHA_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: EWHA_HEIGHT_GRIDS, buildingBase: EWHA_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30, building-filled, forest lowered + place / photo level evidence, pilot/ewha-sinchon); not a survey' }),
  environment: Object.freeze({ provenance: EWHA_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the place models estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: EWHA_ENV_IDS, castShadow: Object.freeze([]), materialHook: createSkkuGroundLook(EWHA_LOOK, EWHA_ZONES),
      // context.json display fade (preview.js FADE): campus clear to r0, the backdrop melts into the haze by r1
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, ...(FADE.linearShare ? { linear: FADE.linearShare } : {}), colour: HAZE }), playMargin_m: 30,
      source: 'pilot/ewha-sinchon preview ground + planting + landscape + context, baked' }),
  }),
  // Protected (pilot destructible:false: 대학교회 - religious, 이화유치원 - child facility, user decision 2026-10-23): never destructible; weapons meet the protective
  // shield (src/protected-buildings.js); own manifest, models packed with the campus cache.
  protected: Object.freeze({
    ...(EWHA_PROTECTED.length ? { manifestURL: asset('protected/manifest.json') } : {}),
    models: EWHA_PROTECTED,
  }),
  // Hazard tape around every destructible building only (src/engine/hazard-tape.js): none on the protected models or the context.
  hazardTape: Object.freeze({ footprints: EWHA_FOOTPRINTS }),
  scene: Object.freeze({
    // preview.js: hemisphere (#fff, #7d8a78, 1.35), sun #fff4e2 3.1 from (-190, 360, -40) towards (30, 10, -330) -> that direction (-220, 350, 290), halved
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 650, far: 2200 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-110, 175, 145]), shadowSpan: 280 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: EWHA_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default EWHA;
